import * as http from 'node:http';
async function main(): Promise<void> {
  const srv = http.createServer((req, res) => {
    if (req.url === '/a') {
      res.setHeader('X-Multi', ['a', 'b']);
      res.setHeader('x-num', 5);
      res.setHeader('X-Gone', 'g');
      res.removeHeader('x-gone');
      const before = res.headersSent;
      res.end(JSON.stringify({
        before, has: [res.hasHeader('X-NUM'), res.hasHeader('x-gone')], num: res.getHeader('x-num'), multi: res.getHeader('X-Multi'),
        missing: res.getHeader('nope') === undefined, names: res.getHeaderNames().sort(), all: res.getHeaders(), after: res.headersSent,
      }));
      return;
    }
    const extra = { 'x-from-var': 'v', 'x-n': 7 };
    res.writeHead(201, extra);
    res.end('created:' + res.headersSent);
  });
  await new Promise<void>((r) => srv.listen(0, '127.0.0.1', () => r()));
  const base = 'http://127.0.0.1:' + (srv.address() as any).port;
  const a = await fetch(base + '/a');
  console.log(a.status, a.headers.get('x-multi'), a.headers.get('x-num'), await a.text());
  const b = await fetch(base + '/b');
  console.log(b.status, b.headers.get('x-from-var'), b.headers.get('x-n'), await b.text());
  srv.close();
}
